// From the repository root: node Labs/FootIKLab/verify-surface.mjs
// Forward inputs use the tracked gait banks via test-bank.cjs. Other directions
// use .nn-cache/directional-{walk,run}-{backward,left,right}.json, generated by
// verify-directional-nn.py using the project's existing single-thread NN runtime.
// Runs all 60 cases sequentially; no server or inference runs during this test.
import fs from 'node:fs';
import crypto from 'node:crypto';
import assert from 'node:assert/strict';
import {createRequire} from 'node:module';
const require=createRequire(import.meta.url),F=require('./surface.js'),K=require('./footik.js'),R=require('./recovery.js'),S=require('./support.js'),{load}=require('./test-bank.cjs');
const rig=JSON.parse(fs.readFileSync(new URL('data/rig.json',import.meta.url)));
const checks=[],cases=[],models=new Map(),check=(name,ok)=>{assert(ok,name);checks.push(name);};
const distance=(a,b)=>R.length(R.sub(a,b)),rad=q=>R.length(R.qlog(q));
const finite=p=>p.points.flat().every(Number.isFinite)&&p.q.flat().every(Number.isFinite);
for(const gait of ['walk','run'])for(const direction of ['forward','backward','left','right']){
 const source=direction==='forward'?null:JSON.parse(fs.readFileSync(new URL(`.nn-cache/directional-${gait}-${direction}.json`,import.meta.url))),run=source?K.decode(source,rig.parents):load(gait,.21);
 for(const approach of ['toward','parallel'])for(const slopeAngle of direction==='forward'?[0,30,45,60,75,90]:[0,45,90]){
  const label=`${gait}${direction==='forward'?'':' '+direction} ${approach} ${slopeAngle}deg`,start=performance.now(),model=F.prepare(run,{gait,direction,approach,slopeAngle}),milliseconds=performance.now()-start;
  models.set(label,model);
  let maxBoneError=0,maxRootVelocityResidual=0,maxRootPositionResidual=0,maxPinSlip=0,maxUprightError=0,upperError=0,ballistic=0,minHeadingDot=1,minRootPlaneGap=Infinity;
  const activePins=new Map();
  for(let i=0;i<model.frames.length;i++){
   const f=model.frames[i],b=f.raw;
   for(let j=2;j<run.names.length;j++)maxBoneError=Math.max(maxBoneError,Math.abs(distance(f.pose.points[j],f.pose.points[run.parents[j]])-distance(b.points[j],b.points[run.parents[j]])));
   for(let j=1;j<run.names.length;j++)if(!/^(thigh|calf|foot|ball)_/.test(run.names[j]))upperError=Math.max(upperError,distance(f.pose.points[j],b.points[j]),rad(R.qm(f.pose.q[j],R.qinv(b.q[j]))));
   for(const foot of f.feet)if(foot.contact){
    const c=foot.contact,key=c.stanceId+':'+c.localPoint.map(x=>Math.round(x*1e6)).join(','),old=activePins.get(key);
    if(old)maxPinSlip=Math.max(maxPinSlip,distance(c.point,old));else activePins.set(key,c.point);
    const l=S.leg(f.pose,run.names,foot.side),nn=K.at(run,i/120),src=S.footFrame(nn,l.foot,l.toe,foot.side),shown=S.footFrame(f.pose,l.foot,l.toe,foot.side),expected=R.rotate(R.fromTo([0,1,0],c.normal),R.unit([src.forward[0],0,src.forward[2]])),project=v=>R.unit(R.sub(v,R.mul(c.normal,R.dot(v,c.normal))));
    minHeadingDot=Math.min(minHeadingDot,R.dot(project(shown.forward),project(expected)));
   }
   maxUprightError=Math.max(maxUprightError,Math.acos(Math.max(-1,Math.min(1,R.dot(f.surface.bodyUp,[0,1,0]))))*180/Math.PI);
   for(const surface of model.terrain.surfaces){const p=surface.local(f.surface.mass),[x0,x1,z0,z1]=surface.bounds;if(p[0]>=x0&&p[0]<=x1&&p[2]>=z0&&p[2]<=z1)minRootPlaneGap=Math.min(minRootPlaneGap,p[1]);}
   if(i+1<model.frames.length){
    const a=f.surface,n=model.frames[i+1].surface,expectedVelocity=R.add(R.add(a.velocity,R.mul(a.acceleration,1/120)),a.collisionImpulse),expectedPosition=R.add(R.add(a.mass,R.mul(R.add(a.velocity,R.mul(a.acceleration,1/120)),1/120)),a.collisionCorrection);
    maxRootVelocityResidual=Math.max(maxRootVelocityResidual,distance(n.velocity,expectedVelocity));maxRootPositionResidual=Math.max(maxRootPositionResidual,distance(n.mass,expectedPosition));
    if(!a.contacts&&R.length(a.supportForce)<1e-8&&R.length(a.drive)<1e-8&&R.length(a.collisionImpulse)<1e-8){ballistic++;checkGravity(a);}
   }
  }
  function checkGravity(a){assert(distance(a.acceleration,[0,-9.81,0])<1e-10,`${label}: free-flight root acceleration must be world gravity`);}
  check(label+' finite poses and deterministic120Hz sampling',model.frames.length===601&&model.frames.every(f=>finite(f.pose))&&model.sample(2)===model.frames[240]&&model.sample(1)===model.frames[120]);
  check(label+' root follows force integration and collision impulses',maxRootVelocityResidual<1e-9&&maxRootPositionResidual<1e-9);
  check(label+' root collider never tunnels through finite planes',minRootPlaneGap>=.22-1e-8);
  check(label+' actual shoe geometry clears both finite surfaces',model.metrics.maxPenetration<.0001);
  check(label+' accepted feet obey leg reach and source bone lengths',model.metrics.maxReachError<1e-7&&maxBoneError<1e-9);
  // Rolling/yaw re-anchoring can revisit the same local corner with a slightly
  // different world pivot. Bound that cumulative shift to0.5mm; the solved
  // active pivot is still exact, including during the yaw correction itself.
  check(label+' material contact does not slide',model.metrics.maxContactDrift<1e-8&&maxPinSlip<5e-4);
  check(label+' contact shoe heading respects the actual directional NN',minHeadingDot>.3);
  check(label+' body retains NN articulation and upright bias',upperError<1e-8&&maxUprightError<=slopeAngle*.55+.01);
  check(label+' knee and ankle motion remain bounded',model.metrics.maxKneeStep<20&&model.metrics.maxAnkleStep<18&&model.metrics.maxRelativeAnkleDegrees<72);
  check(label+' natural and reach roll share300deg/s total allowance',model.metrics.maxPinAngleStep<=300/120+1e-9);
  check(label+' actual incline foot contacts occur',model.metrics.wallContactFrames>0);
  if(slopeAngle>=75)check(label+' wall contact never expires on elapsed time',model.events.every(e=>e.type!=='wall-release'&&e.reason!=='support-budget')&&model.frames.every(f=>!f.surface.wallExpired));
  if(slopeAngle===45&&approach==='toward')check(label+' root physically climbs the incline',model.frames.at(-1).surface.mass[1]>3&&model.frames.at(-1).surface.mass[2]>4);
  cases.push({gait,direction,approach,slopeAngle,milliseconds,metrics:model.metrics,maxBoneError,maxPinSlip,minHeadingDot,minRootPlaneGap,maxRootVelocityResidual,maxRootPositionResidual,maxUprightError,upperError,ballisticFrames:ballistic,wallRelease:model.events.find(e=>e.type==='wall-release')?.frame??null});
 }
}
const walk=load('walk',.21),normal=models.get('walk parallel 90deg'),noGravity=F.prepare(walk,{gait:'walk',approach:'parallel',slopeAngle:90},{gravity:0}),noSupport=F.prepare(walk,{gait:'walk',approach:'parallel',slopeAngle:90},{support:false});
const noSupportNoGravity=F.prepare(walk,{gait:'walk',approach:'parallel',slopeAngle:90},{support:false,gravity:0});
check('Removing gravity changes an unsupported trajectory',distance(noSupport.frames.at(-1).surface.mass,noSupportNoGravity.frames.at(-1).surface.mass)>10);
check('Supported gravity is balanced by actual traction, not disabled',normal.frames.some(f=>f.surface.contacts>0&&distance(f.surface.gravity,[0,-9.81,0])<1e-10&&R.length(f.surface.drive)>9));
check('Disabling support gives zero active force and no pins',noSupport.frames.every(f=>f.feet.every(x=>!x.contact)&&R.length(f.surface.supportForce)===0&&R.length(f.surface.drive)===0));
check('Contact traction changes the trajectory compared with gravity alone',distance(normal.frames[120].surface.mass,noSupport.frames[120].surface.mass)>.3);
const replay=F.prepare(walk,{gait:'walk',approach:'toward',slopeAngle:45}),original=models.get('walk toward 45deg');
check('Full replay and reverse seeking are reproducible',replay.frames.every((f,i)=>distance(f.surface.mass,original.frames[i].surface.mass)<1e-12&&distance(replay.sample((600-i)/120).pose.points[1],original.frames[600-i].pose.points[1])<1e-12));
check('Input bounds keep the prototype finite',F.settings({slopeAngle:Infinity,upright:NaN}).slopeAngle===45&&F.settings({slopeAngle:120,upright:-1}).slopeAngle===90&&F.settings({upright:-1}).upright===0);
// Contact acquisition now retains the incoming shoe rotation, so the capture
// and release tick can change. Check the whole backward stance/release window,
// not that a historical pin ID still exists on one arbitrary frame.
for(const approach of ['toward','parallel']){
 const model=models.get(`walk backward ${approach} 45deg`),releases=model.events.filter(e=>e.type==='release'&&e.side==='L');
 check(`Backward ${approach}45 keeps contact and smooth releases`,releases.length>0&&model.metrics.maxKneeStep<8&&releases.every(e=>{const window=model.frames.slice(Math.max(0,e.frame*2-12),e.frame*2+12);return window.some(f=>f.feet[0].contact)&&window.every(f=>f.feet[0].error<1e-7&&f.feet[0].penetration<1e-4);}));
}
check('Backward gaits exercise both valid heel and toe reach corrections',cases.filter(c=>c.direction==='backward').some(c=>c.metrics.reachRollNegative>0)&&cases.filter(c=>c.direction==='backward').some(c=>c.metrics.reachRollPositive>0));
const report={passed:true,checks,cases,sourceSha256:crypto.createHash('sha256').update(fs.readFileSync(new URL('surface.js',import.meta.url))).digest('hex'),physics:'120Hz semi-implicit integration of world gravity + bounded stance support/traction, with finite capsule-plane collision impulses; contact-driven wall support; NN articulation remains the source.',references:['https://rapier.rs/docs/user_guides/javascript/character_controller/','https://box2d.org/documentation3d/md_character.html'],limitations:['Mass-point/capsule root and kinematic limb IK prototype, not a Jolt ragdoll.','Initial gait remains the current frozen NN input; the surface controller does not retrain or claim online policy feedback.','Parallel mode starts on the incline; toward mode starts on its flat entry.','Wall contact ends through gait, reach, ankle or collision limits, not elapsed time.']};
fs.writeFileSync(new URL('surface-verification.json',import.meta.url),JSON.stringify(report,null,2));console.log(JSON.stringify({passed:true,checks:checks.length,cases:cases.length,maxKneeStep:Math.max(...cases.map(c=>c.metrics.maxKneeStep)),maxAnkleStep:Math.max(...cases.map(c=>c.metrics.maxAnkleStep)),maxPenetration:Math.max(...cases.map(c=>c.metrics.maxPenetration)),milliseconds:cases.reduce((n,c)=>n+c.milliseconds,0)}));
